test_that("method construction and execution work", {m<-new_sblrbench_method("mock","Mock",c("pip","pip"),function(x)x,function(x)x,predict=function(x,...)x);expect_s3_class(m,"sblrbench_method");expect_identical(m$capabilities,"pip");expect_equal(run_sblrbench_method(m,2),2);expect_error(new_sblrbench_method("Bad id","Bad",fit=identity,extract=identity),"machine-readable");expect_error(new_sblrbench_method("x","X",fit=1,extract=identity),"fit");expect_error(new_sblrbench_method("x","X",fit=identity,extract=1),"extract");expect_s3_class(list(mock=m)$mock,"sblrbench_method")})
